'use client';

import { useEffect, useMemo, useState } from 'react';
import Link from 'next/link';
import AppShell from '@/components/Navbar';
import { api } from '@/lib/api';
import { me, type AuthUser } from '@/lib/auth';

interface RoomApi {
  id: number;
  room_number: string;
  building: string;
  capacity: number;
  is_available: boolean;
  type: { id: number; name: string } | null;
}

interface RoomsResponse {
  success: boolean;
  message: string;
  data: RoomApi[];
  meta?: { total: number; page: number; per_page: number };
}

const DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'] as const;

export default function InstructorRoomsPage() {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [rooms, setRooms] = useState<RoomApi[]>([]);
  const [query, setQuery] = useState('');
  const [typeId, setTypeId] = useState<string>('all');
  const [day, setDay] = useState<string>('all');
  const [timeStart, setTimeStart] = useState('07:30');
  const [timeEnd, setTimeEnd] = useState('09:00');
  const [availableOnly, setAvailableOnly] = useState(true);

  const fetchRooms = async () => {
    try {
      setLoading(true);
      setError(null);
      const params = new URLSearchParams();
      if (availableOnly) params.set('available_only', '1');
      if (typeId !== 'all') params.set('type_id', typeId);
      if (day !== 'all') {
        params.set('day', day);
        params.set('time_start', timeStart);
        params.set('time_end', timeEnd);
      }
      params.set('per_page', '100');
      const res = await api.get<RoomsResponse>(`/instructor/rooms?${params.toString()}`);
      setRooms(Array.isArray(res.data) ? res.data : []);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to load rooms.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    me().then(setUser).catch(() => null);
  }, []);

  useEffect(() => {
    fetchRooms();
  }, [typeId, day, timeStart, timeEnd, availableOnly]);

  const filteredRooms = useMemo(() => {
    if (!query.trim()) return rooms;
    const q = query.toLowerCase();
    return rooms.filter((r) =>
      r.room_number.toLowerCase().includes(q) ||
      r.building.toLowerCase().includes(q) ||
      (r.type?.name ?? '').toLowerCase().includes(q)
    );
  }, [rooms, query]);

  const typeOptions = useMemo(() => {
    const map = new Map<number, string>();
    rooms.forEach((r) => {
      if (r.type?.id && r.type?.name) map.set(r.type.id, r.type.name);
    });
    return Array.from(map.entries()).map(([id, name]) => ({ id, name }));
  }, [rooms]);

  return (
    <AppShell role="instructor" userName={user ? `${user.first_name} ${user.last_name}` : 'Instructor'} pageTitle="Browse Rooms">
      <div className="space-y-5">
        <div className="flex items-start justify-between gap-3 flex-wrap">
          <div>
            <h1 className="text-[20px] font-bold" style={{ color: 'var(--color-text)' }}>Browse Rooms</h1>
            <p className="text-[13px]" style={{ color: 'var(--color-text-muted)' }}>
              Find available rooms and create a room request.
            </p>
          </div>
          <Link href="/requests/create" className="btn btn-primary text-[13px]">New Request</Link>
        </div>

        <div className="card card-body grid grid-cols-1 md:grid-cols-2 lg:grid-cols-6 gap-3">
          <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search room/building/type" />

          <select value={typeId} onChange={(e) => setTypeId(e.target.value)}>
            <option value="all">All Types</option>
            {typeOptions.map((t) => <option key={t.id} value={String(t.id)}>{t.name}</option>)}
          </select>

          <select value={day} onChange={(e) => setDay(e.target.value)}>
            <option value="all">All Days</option>
            {DAYS.map((d) => <option key={d} value={d}>{d}</option>)}
          </select>

          <input type="time" value={timeStart} onChange={(e) => setTimeStart(e.target.value)} disabled={day === 'all'} />
          <input type="time" value={timeEnd} onChange={(e) => setTimeEnd(e.target.value)} disabled={day === 'all'} />

          <label className="flex items-center gap-2 text-[12px]">
            <input type="checkbox" checked={availableOnly} onChange={(e) => setAvailableOnly(e.target.checked)} />
            Available only
          </label>
        </div>

        {error && (
          <div className="p-3 rounded-lg border text-[12px]" style={{ borderColor: '#fecaca', background: '#fff1f2', color: '#9f1239' }}>
            {error}
          </div>
        )}

        <div className="card overflow-hidden">
          <div className="card-body pb-2 flex items-center justify-between">
            <h2 className="text-[14px] font-semibold">Rooms</h2>
            <span className="text-[12px]" style={{ color: 'var(--color-text-muted)' }}>
              {loading ? 'Loading...' : `${filteredRooms.length} result(s)`}
            </span>
          </div>
          <div className="overflow-x-auto">
            <table className="table-base">
              <thead>
                <tr>
                  <th>Room</th>
                  <th>Building</th>
                  <th>Type</th>
                  <th>Capacity</th>
                  <th>Status</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {filteredRooms.map((room) => (
                  <tr key={room.id}>
                    <td className="text-[12px] font-semibold">{room.room_number}</td>
                    <td className="text-[12px]">{room.building}</td>
                    <td className="text-[12px]">{room.type?.name ?? 'N/A'}</td>
                    <td className="text-[12px]">{room.capacity}</td>
                    <td className="text-[12px]">{room.is_available ? 'Available' : 'Unavailable'}</td>
                    <td>
                      {room.is_available ? (
                        <Link href={`/requests/create?roomId=${room.id}`} className="btn btn-sm btn-outline text-[11px]">
                          Request
                        </Link>
                      ) : null}
                    </td>
                  </tr>
                ))}
                {!loading && filteredRooms.length === 0 && (
                  <tr>
                    <td colSpan={6} className="text-center text-[12px]" style={{ color: 'var(--color-text-muted)' }}>
                      No rooms found for current filters.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </AppShell>
  );
}
